#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "repo-vul/src-vul/libspng/spng.h"

struct buf_state
{
    const unsigned char *data;
    size_t bytes_left;
};

static int buffer_read_fn(spng_ctx *ctx, void *user, void *dest, size_t length)
{
    struct buf_state *state = (struct buf_state*)user;

    if(length > state->bytes_left) return SPNG_IO_EOF;

    memcpy(dest, state->data, length);

    state->bytes_left -= length;
    state->data += length;

    return 0;
}

int main(int argc, char **argv)
{
    if(argc < 2) {
        printf("Usage: %s <png_file>\n", argv[0]);
        return 1;
    }

    FILE *f = fopen(argv[1], "rb");
    if(!f) {
        printf("Cannot open file\n");
        return 1;
    }

    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);

    unsigned char *data = malloc(size);
    fread(data, 1, size, f);
    fclose(f);

    int ret;
    unsigned char *out = NULL;

    spng_ctx *ctx = spng_ctx_new(0);
    if(ctx == NULL) {
        printf("Failed to create context\n");
        free(data);
        return 1;
    }

    struct buf_state state;
    state.data = data;
    state.bytes_left = size;

    /* Try both streaming and non-streaming modes */
    int flags = 0;
    int fmt = SPNG_FMT_RGBA8;
    int stream = 0;

    if(stream) ret = spng_set_png_stream(ctx, buffer_read_fn, &state);
    else ret = spng_set_png_buffer(ctx, (void*)data, size);

    if(ret) {
        printf("spng_set_png_buffer failed: %d\n", ret);
        goto err;
    }

    spng_set_image_limits(ctx, 200000, 200000);
    spng_set_chunk_limits(ctx, 4 * 1000 * 1000, 8 * 1000 * 1000);
    spng_set_crc_action(ctx, SPNG_CRC_USE, SPNG_CRC_USE);

    size_t out_size;
    if(spng_decoded_image_size(ctx, fmt, &out_size)) {
        printf("spng_decoded_image_size failed\n");
        goto err;
    }

    if(out_size > 80000000) {
        printf("Image too large: %zu\n", out_size);
        goto err;
    }

    out = (unsigned char*)malloc(out_size);
    if(out == NULL) {
        printf("malloc failed\n");
        goto err;
    }

    ret = spng_decode_image(ctx, out, out_size, fmt, flags);
    if(ret) {
        printf("spng_decode_image failed: %d\n", ret);
        goto err;
    }

    printf("Success! Decoded %zu bytes\n", out_size);

err:
    spng_ctx_free(ctx);
    if(out != NULL) free(out);
    free(data);

    return 0;
}
EOF

